def transform(grid):
    h, w = len(grid), len(grid[0])
    # The 1s mark separators; copy the colored pattern in the first tile
    # to each tile of the same size.
    rows = [i for i in range(h) if all(v == 1 for v in grid[i])]
    cols = [j for j in range(w) if all(grid[i][j] == 1 for i in range(h))]
    rh = rows[0] if rows else h
    cw = cols[0] if cols else w

    out = [row[:] for row in grid]
    pattern = [(i, j, grid[i][j])
               for i in range(rh) for j in range(cw)
               if grid[i][j] not in (1, 6)]
    for r0 in range(0, h, rh + 1):
        for c0 in range(0, w, cw + 1):
            for i, j, color in pattern:
                if r0 + i < h and c0 + j < w:
                    out[r0 + i][c0 + j] = color
    return out
